   guaranteeTopUp:r.floor,totalComp:r.totalComp,revenue:r.revenue,ebitda:r.ebitda,
   enterpriseValue:r.ev,evGrowth:r.evg,floor:r.floor,signOn:r.signon,
   relocation:r.reloc,housing:r.housing,retention:r.retention,milestone:r.milestone,
   rsu:r.rsu,psu:r.psu,options:r.opt,phantom:r.phantom,peExit:r.peExit,
   benefits:r.perks,retirement:r.retire,longTerm:r.longTerm,
